#!/usr/bin/env bash
set -Eeuo pipefail
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; cd "$ROOT_DIR"; C="${1:-tinyimx-m21-gateway-a-1}"; SECONDS="${2:-60}"; STAMP="$(date +%Y%m%d-%H%M%S)"; ART="${M21_PERF_ARTIFACT_DIR:-$ROOT_DIR/artifacts/m21-perf-$STAMP}";mkdir -p "$ART";command -v perf >/dev/null||{ echo "perf missing" >&2;exit 1;};PID="$(docker inspect -f '{{.State.Pid}}' "$C")";[[ "$PID" =~ ^[1-9][0-9]*$ ]];echo "container=$C host_pid=$PID"|tee "$ART/deployment.txt";perf record -F 99 -g -p "$PID" -o "$ART/perf.data" -- sleep "$SECONDS";perf report --stdio -i "$ART/perf.data" > "$ART/perf-report.txt";if [[ -n "${FLAMEGRAPH_DIR:-}" && -x "$FLAMEGRAPH_DIR/stackcollapse-perf.pl" && -x "$FLAMEGRAPH_DIR/flamegraph.pl" ]];then perf script -i "$ART/perf.data"|"$FLAMEGRAPH_DIR/stackcollapse-perf.pl" > "$ART/perf.folded";"$FLAMEGRAPH_DIR/flamegraph.pl" "$ART/perf.folded" > "$ART/flamegraph.svg";echo "M21_FLAMEGRAPH=PASS path=$ART/flamegraph.svg";else echo "M21_FLAMEGRAPH=SKIPPED reason=FLAMEGRAPH_DIR_not_configured";fi;echo "M21_PERF_CAPTURE=PASS";echo "M21_PERF_ARTIFACT_DIR=$ART"
